INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (408997, 16348, 'The Atlantic', 'en', 'Why Did John Ratcliffe Go to Moscow?', 'https://www.theatlantic.com/international/2026/08/cia-director-ratcliffe-moscow/688424', 'Despite Trump’s claims, the CIA director’s visit was anything but routine. It might be a sign that Putin is getting more dangerous.', 'https://cdn.theatlantic.com/thumbor/SgOtyO4sLSmZYJsJxEG6UWPsnX0=/media/img/mt/2026/08/2026_08_26_Ratcliffe_in_Russia_Jack_Segelstein/original.jpg', '2026-08-26T22:06:00+00:00', '2026-08-27T00:08:31.090541'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (422579, 16348, 'The Guardian', 'en', 'Trump downplays Moscow visit by CIA director as ‘semi-routine’', 'https://www.theguardian.com/us-news/2026/aug/26/trump-cia-director-moscow-visit', 'President denies visit was to gain support for Iran sanctions or due to fears that Putin plans to ‘test Nato resolve’ Donald Trump has downplayed a visit to Moscow by the CIA director, John Ratcliffe, as “semi-routine” after he turned up in the Russian capital unannounced, triggering a wave of speculation about the reasons for his trip. Ratcliffe was reported to have flown to Moscow on a government transport plane on Tuesday in a rare visit after taking off from the Andrews air force base in Maryland. Continue reading...', 'https://i.guim.co.uk/img/media/98bf0083a520236fb573a198df1f3f785590404a/579_0_5792_4635/master/5792.jpg?width=140&quality=85&auto=format&fit=max&s=5a6673e6f8f8de02de78c034255fd566', '2026-08-26T18:21:52+00:00', '2026-08-28T12:49:05.741180'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
